package com.bank.drift;

import java.util.*;

// The REAL attributes in the cloud (can be changed out-of-band).
public class CloudReality {
    final Map<String,String> attrs = new LinkedHashMap<>();
    final Set<String> resources = new LinkedHashSet<>();
    public void set(String resource, String attr, String value) { resources.add(resource); attrs.put(resource + "." + attr, value); }
    public String get(String resource, String attr) { return attrs.get(resource + "." + attr); }
    public boolean exists(String resource) { return resources.contains(resource); }
}
