package com.bank.drift;

import java.util.*;

// DECLARED attributes Terraform believes are true + which resources it tracks.
public class TerraformState {
    final Map<String,String> declared = new LinkedHashMap<>();
    final Set<String> tracked = new LinkedHashSet<>();
    public void declare(String resource, String attr, String value) { tracked.add(resource); declared.put(resource + "." + attr, value); }
    public String get(String resource, String attr) { return declared.get(resource + "." + attr); }
    public boolean tracks(String resource) { return tracked.contains(resource); }
    public void importResource(String resource, String attr, String value) { declare(resource, attr, value); }
    public void adopt(String resource, String attr, String value) { declared.put(resource + "." + attr, value); }
}
