package com.bank.drift;

import java.util.*;
import java.util.logging.Logger;

// terraform plan: refresh reality vs state and report drift.
public class DriftDetector {
    private static final Logger log = Logger.getLogger(DriftDetector.class.getName());

    public List<String> plan(CloudReality real, TerraformState state, String resource, String attr) {
        List<String> drift = new ArrayList<>();
        if (!state.tracks(resource) && real.exists(resource)) {
            log.warning(() -> "DRIFT: " + resource + " exists in cloud but is NOT tracked -> candidate for import");
            drift.add("untracked:" + resource);
            return drift;
        }
        String declared = state.get(resource, attr), actual = real.get(resource, attr);
        if (!Objects.equals(declared, actual)) {
            log.warning(() -> "DRIFT: " + resource + "." + attr + " declared=" + declared + " actual=" + actual);
            drift.add("changed:" + resource + "." + attr);
        } else {
            log.info(() -> "no drift for " + resource + "." + attr);
        }
        return drift;
    }
}
