package com.bank.drift;

import java.util.logging.Logger;

// Three reconciliation strategies: re-apply, update-config(adopt), import.
public class Reconciler {
    private static final Logger log = Logger.getLogger(Reconciler.class.getName());

    // revert reality to the declared config (code wins)
    public void reapply(CloudReality real, TerraformState state, String resource, String attr) {
        String declared = state.get(resource, attr);
        real.set(resource, attr, declared);
        log.info(() -> "re-apply: reverted " + resource + "." + attr + " back to declared=" + declared);
    }
    // adopt the out-of-band change into config (reality wins, codified)
    public void adopt(CloudReality real, TerraformState state, String resource, String attr) {
        String actual = real.get(resource, attr);
        state.adopt(resource, attr, actual);
        log.info(() -> "update-config: adopted " + resource + "." + attr + " = " + actual + " into code/state");
    }
    // bring an untracked resource under management
    public void importResource(CloudReality real, TerraformState state, String resource, String attr) {
        String actual = real.get(resource, attr);
        state.importResource(resource, attr, actual);
        log.info(() -> "import: " + resource + " now tracked (" + attr + "=" + actual + ")");
    }
}
