package com.bank.drift;

import java.math.BigDecimal;
import java.util.logging.*;

public class DriftDemo {
    private static final Logger log = Logger.getLogger(DriftDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        CloudReality real = new CloudReality();
        TerraformState state = new TerraformState();
        DriftDetector detector = new DriftDetector();
        Reconciler reconciler = new Reconciler();

        // Declared + real agree initially for the ledger DB
        state.declare("aws_db_instance.ledger", "instance_class", "db.m5.large");
        real.set("aws_db_instance.ledger", "instance_class", "db.m5.large");

        // Out-of-band: on-call bumped DB class during an incident
        real.set("aws_db_instance.ledger", "instance_class", "db.m5.2xlarge");
        detector.plan(real, state, "aws_db_instance.ledger", "instance_class");
        // DECISION: the bigger class is actually needed -> adopt into code (reality wins)
        reconciler.adopt(real, state, "aws_db_instance.ledger", "instance_class");
        detector.plan(real, state, "aws_db_instance.ledger", "instance_class");  // no drift now

        // Untracked security group rule created in console -> import
        real.set("aws_security_group_rule.ledger_allow", "port", "5432");
        detector.plan(real, state, "aws_security_group_rule.ledger_allow", "port");
        reconciler.importResource(real, state, "aws_security_group_rule.ledger_allow", "port");

        // Correctly reconciled DB backs a real transfer
        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS on reconciled ledger DB");
    }
}
